  "version": "0.0.0",
  "private": true,
  "description": "Bloom HttpApi contract (effect/http-api). Shared by the server, the web client, and OpenAPI emission.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./*": "./src/*.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "bun test --pass-with-no-tests",
    "openapi": "bun run scripts/emit-openapi.ts"
  },
  "dependencies": {
    "@bloom/domain": "workspace:*",
    "effect": "4.0.0"
  }
}
import { HttpApi, OpenApi } from "effect/http-api";
import { HealthGroup } from "./groups/health.ts";
import { MeGroup } from "./groups/me.ts";
import { MessagesGroup } from "./groups/messages.ts";
import { TasksGroup } from "./groups/tasks.ts";
import { ThreadsGroup } from "./groups/threads.ts";

/**
 * The Bloom HTTP API: single source of truth for server handlers
 * (`HttpApiBuilder`), the web client (`HttpApiClient`) and `openapi.json`.
 *
 * Every route lives under `/api` (ADR 0004). `/api/auth/*` belongs to Better
 * Auth and is deliberately not part of this contract.
 */
export class BloomApi extends HttpApi.make("bloom")
  .add(HealthGroup, MeGroup, ThreadsGroup, MessagesGroup, TasksGroup)
  .prefix("/api")
  .annotateMerge(
    OpenApi.annotations({
      title: "Bloom API",
      version: "0.1.0",
      description:
        "HTTP contract of the Bloom personal agent. Authenticated routes rely on the Better Auth session cookie; chat replies stream as Server-Sent Events.",
    }),
  ) {}
import { UserId } from "@bloom/domain";
import { Context, Schema } from "effect";
import { HttpApiMiddleware } from "effect/http-api";

/** The authenticated owner as the API sees them; the wire shape of `GET /api/me`. */
export const AuthUser = Schema.Struct({
  id: UserId,
  email: Schema.String,
  name: Schema.String,
});
export type AuthUser = typeof AuthUser.Type;

/** Request-scoped service carrying the authenticated user; provided by `Authorization`. */
export class CurrentUser extends Context.Service<CurrentUser, AuthUser>()(
  "bloom/api/CurrentUser",
) {}

/** No valid session on the request. Encoded as HTTP 401. */
export class Unauthorized extends Schema.TaggedError<Unauthorized>()(
  "Unauthorized",
  { message: Schema.String },
  { httpApiStatus: 401 },
) {}

/**
 * Authorization middleware for every non-public endpoint.
 *
 * It declares no security scheme and is not `requiredForClient`: the browser
 * sends the Better Auth session cookie automatically and the server
 * implementation (in `apps/server`) reads the request headers itself. This
 * package only defines the contract; the implementation provides
 * `CurrentUser` to the wrapped handler or fails with `Unauthorized`.
 */
export class Authorization extends HttpApiMiddleware.Service<
  Authorization,
  { provides: CurrentUser }
>()("bloom/api/Authorization", { error: Unauthorized }) {}
import { Context, type Effect, Layer } from "effect";
import { FetchHttpClient, type HttpClient } from "effect/http";
import { HttpApiClient } from "effect/http-api";
import { BloomApi } from "./api.ts";

/** Options for the derived client. */
export interface BloomClientOptions {
  /**
   * Origin to prepend to every request, e.g. `http://localhost:3000`.
   * Omit it in the browser: paths already start with `/api` and resolve
   * against `location.origin` (ADR 0004, single origin).
   */
  readonly baseUrl?: string | URL | undefined;
}

/** The typed client shape derived from `BloomApi`. SSE endpoints return a `Stream`. */
export type BloomClientShape = HttpApiClient.ForApi<typeof BloomApi>;

/**
 * Builds the typed client from the API definition. Requires an `HttpClient`
 * (e.g. `FetchHttpClient.layer`); use `BloomClient.layer` for the ready-made
 * service.
 */
export const makeBloomClient = (
  options?: BloomClientOptions,
): Effect.Effect<BloomClientShape, never, HttpClient.HttpClient> =>
  HttpApiClient.make(BloomApi, { baseUrl: options?.baseUrl });

/**
 * The Bloom API client as a service, so the web app can `yield* BloomClient`.
 * `BloomClient.layer()` provides `FetchHttpClient`; the browser attaches the
 * session cookie itself, so no client middleware is required.
 */
export class BloomClient extends Context.Service<BloomClient, BloomClientShape>()(
  "bloom/api/BloomClient",
) {
  static readonly layer = (baseUrl?: string | URL): Layer.Layer<BloomClient> =>
    Layer.effect(BloomClient, makeBloomClient({ baseUrl })).pipe(
      Layer.provide(FetchHttpClient.layer),
    );
}
