/**
 * @bloom/api: the HttpApi contract shared by the server (handlers), the web
 * app (derived client) and the OpenAPI document. No implementation lives here.
 */
export * from "./api.ts";
export * from "./auth.ts";
export * from "./client.ts";
export * from "./groups/errors.ts";
export * from "./groups/health.ts";
export * from "./groups/me.ts";
export * from "./groups/messages.ts";
export * from "./groups/tasks.ts";
export * from "./groups/threads.ts";
export * from "./openapi.ts";
export * from "./payload.ts";
import { OpenApi } from "effect/http-api";
import { BloomApi } from "./api.ts";

/** The OpenAPI 3.1 document for `BloomApi` (a fresh copy on each call). */
export const openApiSpec = (): OpenApi.OpenAPISpec => OpenApi.fromApi(BloomApi);

/** `openApiSpec()` as pretty-printed JSON with a trailing newline, the content of `packages/api/openapi.json`. */
export const renderOpenApiJson = (): string => `${JSON.stringify(openApiSpec(), null, 2)}\n`;
import { Effect, Schema } from "effect";
import { HttpApiError } from "effect/http-api";

/**
 * Decodes an endpoint payload declared with `Schema.toEncoded(X)` into `X`'s
 * decoded type (defaults applied, timestamps parsed).
 *
 * Create endpoints declare their payload as the encoded side of the domain
 * `jsonCreate` variant so the derived TypeScript client can send a minimal
 * body (`{ title }`) instead of every key. The handler then calls
 * `decodePayload(Task.jsonCreate)(payload)` before handing the result to the
 * domain service.
 *
 * The encoded side already enforces the shape, so a decode failure can only
 * come from a value-level check the encoded side cannot express (an ISO
 * timestamp that does not parse, for example). Such a failure becomes
 * `HttpApiError.HttpApiSchemaError` with kind `Payload`, which is exactly what
 * `HttpApiBuilder` raises for its own payload decoding: it renders as an
 * empty `400 Bad Request`.
 */
export const decodePayload = <Source extends Schema.Top>(schema: Source) => {
  const decode = Schema.decodeUnknownEffect(schema);
  return (
    input: Source["Encoded"],
  ): Effect.Effect<Source["Type"], never, Source["DecodingServices"]> =>
    decode(input).pipe(
      Effect.catch((cause) =>
        Effect.die(new HttpApiError.HttpApiSchemaError({ kind: "Payload", cause })),
      ),
    );
};
/**
 * Writes `packages/api/openapi.json` from the `BloomApi` definition.
 *
 * Run from the repo root with `bun run openapi`. An optional first argument
 * overrides the output path (used by the tests).
 */
import { Effect, Schema } from "effect";
import { renderOpenApiJson } from "../src/openapi.ts";

class OpenApiWriteError extends Schema.TaggedError<OpenApiWriteError>()("OpenApiWriteError", {
  path: Schema.String,
  cause: Schema.Defect(),
}) {}

const defaultOutput = new URL("../openapi.json", import.meta.url);
const outputArg = process.argv[2];
const output: string | URL = outputArg === undefined ? defaultOutput : outputArg;
const outputPath = typeof output === "string" ? output : output.pathname;

const program = Effect.gen(function* () {
  const json = renderOpenApiJson();
  yield* Effect.tryPromise({
    try: () => Bun.write(output, json),
    catch: (cause) => new OpenApiWriteError({ path: outputPath, cause }),
  });
  yield* Effect.log(`wrote ${outputPath}`);
}).pipe(Effect.withSpan("emit-openapi"));

await Effect.runPromise(program);

import { Effect, Schema } from "effect";
import { Model } from "effect/schema";

/**
 * Postgres facts these helpers encode: `@effect/sql-pg` decodes `timestamptz`
 * to a JS `Date` and `jsonb` to parsed JSON. DB variants (select/insert/update)
 * therefore use `*FromDate` schemas, while JSON variants use ISO strings.
 */

const TimestampDb = Schema.DateTimeUtcFromDate;
const TimestampJson = Schema.DateTimeUtcFromString;
const NullableTimestampDb = Schema.NullOr(TimestampDb);
const NullableTimestampJson = Schema.NullOr(TimestampJson);

/** Required, caller-supplied timestamp: `Date` in DB variants, ISO string in JSON variants. */
export const Timestamp = Model.Field({
  select: TimestampDb,
  insert: TimestampDb,
  update: TimestampDb,
  json: TimestampJson,
  jsonCreate: TimestampJson,
  jsonUpdate: Schema.optionalKey(TimestampJson),
});

/** Required, caller-supplied, write-once timestamp (e.g. `Event.occurredAt`): absent from update variants. */
export const ImmutableTimestamp = Model.Field({
  select: TimestampDb,
  insert: TimestampDb,
  json: TimestampJson,
  jsonCreate: TimestampJson,
});

/**
 * Nullable, caller-supplied timestamp (due, scheduledFor, ...).
 * Defaults to `null` on insert/jsonCreate when omitted; optional in jsonUpdate.
 */
export const NullableTimestamp = Model.Field({
  select: NullableTimestampDb,
  insert: NullableTimestampDb.pipe(Schema.withConstructorDefault(Effect.succeed(null))),
  update: NullableTimestampDb,
  json: NullableTimestampJson,
  jsonCreate: NullableTimestampJson.pipe(Schema.withDecodingDefaultKey(Effect.succeed(null))),
  jsonUpdate: Schema.optionalKey(NullableTimestampJson),
});

/**
 * Nullable timestamp owned by a domain service (completedAt, lastMessageAt,
 * sentAt, outcomeAt): readable over JSON but absent from jsonCreate/jsonUpdate,
 * so clients cannot set it. Defaults to `null` in the insert constructor.
 */
export const ServerTimestamp = Model.Field({
  select: NullableTimestampDb,
  insert: NullableTimestampDb.pipe(Schema.withConstructorDefault(Effect.succeed(null))),
  update: NullableTimestampDb,
  json: NullableTimestampJson,
});

/**
 * Nullable column. Defaults to `null` on insert/jsonCreate when omitted;
 * optional in jsonUpdate so clients can send partial patches.
 */
export const Nullable = <S extends Schema.Top>(schema: S) => {
  const nullable = Schema.NullOr(schema);
  return Model.Field({
    select: nullable,
    insert: nullable.pipe(Schema.withConstructorDefault(Effect.succeed(null))),
    update: nullable,
    json: nullable,
    jsonCreate: nullable.pipe(Schema.withDecodingDefaultKey(Effect.succeed(null))),
    jsonUpdate: Schema.optionalKey(nullable),
  });
};

/**
 * Required column with a default: filled in by the insert constructor and by
 * jsonCreate decoding when the client omits it; optional in jsonUpdate.
 */
export const WithDefault = <S extends Schema.Top & Schema.WithoutConstructorDefault>(
  schema: S,
  value: S["Encoded"] & S["~type.make.in"],
) =>
  Model.Field({
    select: schema,
    insert: schema.pipe(Schema.withConstructorDefault(Effect.succeed(value))),
    update: schema,
    json: schema,
    jsonCreate: schema.pipe(Schema.withDecodingDefaultKey(Effect.succeed(value))),
    jsonUpdate: Schema.optionalKey(schema),
  });

/** Required column that is required on create but optional in jsonUpdate patches. */
export const Patchable = <S extends Schema.Top>(schema: S) =>
  Model.Field({
    select: schema,
    insert: schema,
    update: schema,
    json: schema,
    jsonCreate: schema,
    jsonUpdate: Schema.optionalKey(schema),
  });

/** Required, immutable column: present on select/insert/json/jsonCreate, absent from update variants. */
export const Immutable = <S extends Schema.Top>(schema: S) =>
  Model.Field({
    select: schema,
    insert: schema,
    json: schema,
    jsonCreate: schema,
  });
