import { AgentRunner, USER_FACING_MODEL_ERROR } from "@bloom/agent";
import { BloomApi } from "@bloom/api";
import { type ChatStreamEvent, ThreadService } from "@bloom/domain";
import { Effect, Stream } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/**
 * Turns the runner's stream into what the SSE contract allows (no failures).
 *
 * `AgentRunner.run` emits an `error` event and then fails with `ModelError`
 * (ADR 0013); the failure is dropped so the response ends cleanly after that
 * event. A `ThreadNotFound` inside the stream can only mean the thread vanished
 * between the handler's check and the run, so it becomes a terminal `error` event.
 */
const threadVanished: ChatStreamEvent = { type: "error", message: USER_FACING_MODEL_ERROR };

export const toSseStream = <R>(
  stream: Stream.Stream<
    ChatStreamEvent,
    { readonly _tag: "ModelError" } | { readonly _tag: "ThreadNotFound" },
    R
  >,
): Stream.Stream<ChatStreamEvent, never, R> =>
  stream.pipe(
    Stream.catchTags({
      ModelError: () => Stream.empty,
      ThreadNotFound: () => Stream.succeed(threadVanished),
    }),
  );

/**
 * `POST /api/threads/:id/messages`. The runner persists the user turn itself,
 * so the handler only verifies the thread (an unknown id is a 404 before any
 * bytes are streamed) and hands the run over as SSE.
 */
export const MessagesLive = HttpApiBuilder.group(
  BloomApi,
  "messages",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const runner = yield* AgentRunner;
    return handlers.handle(
      "send",
      Effect.fn(function* ({ params, payload }) {
        yield* threads.get(params.id);
        return toSseStream(runner.run({ threadId: params.id, text: payload.text }));
      }),
    );
  }),
);
import { BloomApi, decodePayload } from "@bloom/api";
import { Task, TaskService } from "@bloom/domain";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/** `POST /api/tasks` carries the encoded side of `Task.jsonCreate` (ADR 0014). */
const decodeTaskCreate = decodePayload(Task.jsonCreate);

/** Every mutation goes through `TaskService` as the `user` actor, so the audit `Event` is written. */
export const TasksLive = HttpApiBuilder.group(
  BloomApi,
  "tasks",
  Effect.fn(function* (handlers) {
    const tasks = yield* TaskService;
    return handlers.handleAll({
      list: ({ query }) =>
        tasks.list(query.status === undefined ? undefined : { status: query.status }),
      create: ({ payload }) =>
        Effect.flatMap(decodeTaskCreate(payload), (input) => tasks.create(input, "user")),
      get: ({ params }) => tasks.get(params.id),
      update: ({ params, payload }) => tasks.update(params.id, payload, "user"),
      complete: ({ params }) => tasks.complete(params.id, "user"),
      remove: ({ params }) => tasks.remove(params.id, "user"),
    });
  }),
);
import { BloomApi, decodePayload } from "@bloom/api";
import { MessageService, Thread, ThreadService } from "@bloom/domain";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/**
 * `POST /api/threads` carries the encoded side of `Thread.jsonCreate` with
 * `kind` narrowed to `side | quest` (ADR 0014); decoding applies the defaults.
 */
const decodeThreadCreate = decodePayload(Thread.jsonCreate);

/** Threads group: list/create/get/main plus the message history of a thread. */
export const ThreadsLive = HttpApiBuilder.group(
  BloomApi,
  "threads",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const messages = yield* MessageService;
    return handlers.handleAll({
      list: () => threads.list,
      create: ({ payload }) => Effect.flatMap(decodeThreadCreate(payload), threads.create),
      main: () => threads.ensureMain,
      get: ({ params }) => threads.get(params.id),
      messages: ({ params, query }) =>
        threads
          .get(params.id)
          .pipe(
            Effect.flatMap(() =>
              messages.list(params.id, query.limit === undefined ? {} : { limit: query.limit }),
            ),
          ),
    });
  }),
);
/**
 * The HTTP server: API, docs, Better Auth and static routes on one Bun server.
 * CORS stays off (ADR 0004). `HttpRouter.serve` adds the request logger and
 * tracer middleware, so every request is a span with path-only logs, except
 * the magic-link verify request, whose span would carry the token.
 */
import { BunHttpServer } from "@effect/platform-bun";
import { Effect, Layer } from "effect";
import { HttpMiddleware, HttpRouter, HttpServer, type HttpServerRequest } from "effect/http";
import type { SocketAddress } from "effect/net/NetAddress";
import { AUTH_BASE_PATH } from "../auth/auth.ts";
import { AuthRoutes } from "../auth/routes.ts";
import { ServerConfig } from "../config.ts";
import { ApiRoutes, DocsRoute } from "./api.ts";
import { StaticRoutes } from "./static.ts";

/** Every route the server mounts, in one router. Wildcards lose to static/param routes, so `/api/*` always wins. */
export const AllRoutes = Layer.mergeAll(ApiRoutes, DocsRoute, AuthRoutes, StaticRoutes);

/** The magic-link verify endpoint; its `?token=` is a one-time credential (ADR 0003). */
export const MAGIC_LINK_VERIFY_PATH = `${AUTH_BASE_PATH}/magic-link/verify`;

/**
 * Requests that must never become an `http.server` span. The tracer middleware
 * records `url.full` and `url.query` verbatim, which would export the magic-link
 * token to the trace backend; the request logger only logs the path, so it stays on.
 */
export const isTracerDisabledFor = (request: HttpServerRequest.HttpServerRequest): boolean =>
  request.url === MAGIC_LINK_VERIFY_PATH || request.url.startsWith(`${MAGIC_LINK_VERIFY_PATH}?`);

/** `HttpMiddleware.TracerDisabledWhen` set to {@link isTracerDisabledFor}. */
export const TracerDisabledLive = Layer.succeed(HttpMiddleware.TracerDisabledWhen)(
  isTracerDisabledFor,
);

/**
 * Serves `routes` on the current `HttpServer` with the server's middleware
 * policy: request logger on, listen log off, tracer disabled for the verify path.
 */
export const serveRoutes = <A, E, R>(routes: Layer.Layer<A, E, R>) =>
  HttpRouter.serve(routes, { disableListenLog: true }).pipe(Layer.provide(TracerDisabledLive));

const describeAddress = (address: SocketAddress): string =>
  address._tag === "UnixPathAddress" ? address.path : `:${address.port}`;

/** One line once the socket is bound: `bloom-server listening on :3000`. */
export const ListenLog = Layer.effectDiscard(
  Effect.flatMap(HttpServer.HttpServer, (server) =>
    Effect.logInfo(`bloom-server listening on ${describeAddress(server.address)}`),
  ),
);

/**
 * Routes served on whatever `HttpServer` is provided (the integration test
 * binds a random port). The listen line is logged after the routes are mounted.
 */
export const HttpRoutesLive = ListenLog.pipe(Layer.provideMerge(serveRoutes(AllRoutes)));

/**
 * Bun closes a connection that sends nothing for `idleTimeout` seconds (default
 * 10). A chat reply streams nothing while the model thinks, which is routinely
 * longer than that, so the SSE response would be cut off and the run
 * interrupted. 255 is Bun's maximum.
 */
export const IDLE_TIMEOUT_SECONDS = 255;

/** Bun server bound to `PORT` on all interfaces (Tailscale reaches it by hostname). */
export const BunServerLive = Layer.unwrap(
  Effect.map(ServerConfig, (config) =>
    BunHttpServer.layer({
      port: config.port,
      hostname: "0.0.0.0",
      idleTimeout: IDLE_TIMEOUT_SECONDS,
    }),
  ),
);

/** The whole HTTP side. Exposes `HttpServer` so callers can read the bound address. */
export const HttpLive = HttpRoutesLive.pipe(Layer.provideMerge(BunServerLive));
/**
 * bloom-server: the one long-running process. Composition, outermost first:
 *
 *   HTTP + job scheduler (+ integration ingestion, none yet)
 *     <- agent runtime <- model clients <- Better Auth <- database
 *     <- logging/telemetry <- configuration
 *
 * Launch from the repo root so Bun loads `.env`. Missing `DATABASE_URL` or
 * `BETTER_AUTH_SECRET` fails the config layer before anything connects.
 */
import { AgentClientsLive, AgentLive } from "@bloom/agent";
import { DbLive } from "@bloom/db";
import { integrations } from "@bloom/integrations";
import { BunRuntime } from "@effect/platform-bun";
import { Effect, Layer } from "effect";
import { Auth } from "./auth/service.ts";
import { ServerConfig } from "./config.ts";
import { HttpLive } from "./http/server.ts";
import { JobScheduler } from "./jobs/scheduler.ts";
import { ObservabilityLive } from "./observability.ts";

/** Background ingestion of every integration that has one (empty today; iterated generically). */
export const IngestionLive = Layer.mergeAll(
  Layer.empty,
  ...integrations.flatMap((integration) =>
    integration.ingestion === undefined ? [] : [integration.ingestion],
  ),
);

/** The whole server. Exposes `HttpServer` (via `HttpLive`) so tests can read the bound port. */
export const ServerLive = Layer.mergeAll(HttpLive, JobScheduler.layer, IngestionLive).pipe(
  Layer.provide(AgentLive),
  Layer.provide(AgentClientsLive),
  Layer.provide(Auth.layer),
  Layer.provide(DbLive),
  Layer.provide(ObservabilityLive),
  Layer.provide(ServerConfig.layer),
);

if (import.meta.main) {
  BunRuntime.runMain(
    Layer.launch(ServerLive).pipe(
      Effect.tapCause((cause) => Effect.logFatal("bloom-server failed to start", cause)),
    ),
  );
}

import { describe, expect, it } from "bun:test";
import { BloomApi } from "@bloom/api";
import { UserId } from "@bloom/domain";
import { Effect, Layer, Option, Ref, Schema } from "effect";
import { HttpServer, HttpServerRequest } from "effect/http";
import { HttpApiTest } from "effect/http-api";
import { AuthorizationLive, SIGN_IN_MESSAGE, sessionHeaders } from "../src/auth/authorization.ts";
import { Auth, AuthError, type AuthShape, type SessionUser } from "../src/auth/service.ts";
import { MeLive } from "../src/http/groups/me.ts";

const owner: SessionUser = { id: "user-gabby", email: "gabby@example.com", name: "Gabby" };

type SessionResult = Effect.Effect<Option.Option<{ readonly user: SessionUser }>, AuthError>;

/** `Auth` whose `getSession` is scripted; records how many lookups happened. */
const fakeAuth = (session: SessionResult, lookups: Ref.Ref<number>) =>
  Layer.succeed(
    Auth,
    Auth.of({
      handle: () => Effect.die("handle is not used by the middleware"),
      getSession: () => Ref.update(lookups, (n) => n + 1).pipe(Effect.andThen(session)),
      requestMagicLink: () => Effect.void,
    } satisfies AuthShape),
  );

const makeClient = HttpApiTest.groups(BloomApi, ["me"]);

/** Builds the `me` group behind the real middleware over a fake `Auth`. */
const run = <A, E>(
  session: SessionResult,
  body: (client: Effect.Success<typeof makeClient>) => Effect.Effect<A, E>,
) =>
  Effect.runPromise(
    Effect.gen(function* () {
      const lookups = yield* Ref.make(0);
      const handlers = MeLive.pipe(
        Layer.provideMerge(AuthorizationLive),
        Layer.provide(fakeAuth(session, lookups)),
      );
      const result = yield* Effect.flatMap(makeClient, body).pipe(
        Effect.provide(Layer.mergeAll(handlers, HttpServer.layerServices)),
      );
      return { result, lookups: yield* Ref.get(lookups) };
    }).pipe(Effect.scoped),
  );

describe("Authorization middleware", () => {
  it("provides CurrentUser to the handler when a session exists", async () => {
    const { result, lookups } = await run(Effect.succeedSome({ user: owner }), (client) =>
      client.me.get(),
    );
    expect(result).toEqual({
      id: Schema.decodeSync(UserId)(owner.id),
      email: owner.email,
      name: owner.name,
    });
    expect(lookups).toBe(1);
  });

  it("fails with Unauthorized (401) when there is no session", async () => {
    const { result } = await run(Effect.succeedNone, (client) => Effect.flip(client.me.get()));
    expect(result._tag).toBe("Unauthorized");
    if (result._tag === "Unauthorized") {
      expect(result.message).toBe(SIGN_IN_MESSAGE);
    }
  });

  it("treats an Auth failure as Unauthorized rather than a 500", async () => {
    const { result } = await run(
      Effect.fail(new AuthError({ operation: "getSession", cause: new Error("db down") })),
      (client) => Effect.flip(client.me.get()),
    );
    expect(result).toMatchObject({ _tag: "Unauthorized", message: SIGN_IN_MESSAGE });
  });

  it("forwards only the cookie header to Better Auth", () => {
    const request = HttpServerRequest.fromWeb(
      new Request("http://bloom.test/api/me", {
        headers: {
          cookie: "bloom.session_token=abc",
          authorization: "Bearer nope",
          "x-extra": "1",
        },
      }),
    );
    const headers = sessionHeaders(request);
    expect(headers.get("cookie")).toBe("bloom.session_token=abc");
    expect(headers.has("authorization")).toBe(false);
    expect(headers.has("x-extra")).toBe(false);

    const bare = sessionHeaders(HttpServerRequest.fromWeb(new Request("http://bloom.test/api/me")));
    expect(Array.from(bare.keys())).toEqual([]);
  });
});
import { describe, expect, it } from "bun:test";
import { AgentRunner, ModelError, USER_FACING_MODEL_ERROR } from "@bloom/agent";
import { Authorization, BloomApi, CurrentUser } from "@bloom/api";
import {
  type ChatStreamEvent,
  MessageService,
  ThreadId,
  ThreadNotFound,
  ThreadService,
  UserId,
} from "@bloom/domain";
import { Effect, Layer, Schema, Stream } from "effect";
import { HttpServer } from "effect/http";
import { HttpApiTest } from "effect/http-api";
import { MessagesLive, toSseStream } from "../src/http/groups/messages.ts";
import { ThreadsLive } from "../src/http/groups/threads.ts";

const threadId = Schema.decodeSync(ThreadId);
const messageId = Schema.decodeSync(Schema.String.pipe(Schema.brand("MessageId")));

const AuthorizationAllow = Layer.succeed(Authorization)((httpEffect) =>
  Effect.provideService(httpEffect, CurrentUser, {
    id: Schema.decodeSync(UserId)("user-gabby"),
    email: "gabby@example.com",
    name: "Gabby",
  }),
);

const modelError = new ModelError({
  reason: "Upstream",
  provider: "api_key",
  model: "claude-test",
  message: "scripted failure",
});

const start = (id: ThreadId): ChatStreamEvent => ({
  type: "message_start",
  messageId: messageId("m-1"),
  threadId: id,
});
const delta: ChatStreamEvent = { type: "text_delta", messageId: messageId("m-1"), delta: "hi" };
const errorEvent: ChatStreamEvent = { type: "error", message: USER_FACING_MODEL_ERROR };

/** A runner whose stream is scripted per call; records the inputs it received. */
const fakeRunner = (
  script: (input: {
    readonly threadId: ThreadId;
    readonly text: string;
  }) => Stream.Stream<ChatStreamEvent, ModelError | ThreadNotFound>,
  calls: Array<{ readonly threadId: ThreadId; readonly text: string }>,
) =>
  Layer.succeed(
    AgentRunner,
    AgentRunner.of({
      run: (input) => {
        calls.push(input);
        return script(input);
      },
    }),
  );

const makeClient = HttpApiTest.groups(BloomApi, ["threads", "messages"]);

const run = <A, E>(
  runner: Layer.Layer<AgentRunner>,
  body: (client: Effect.Success<typeof makeClient>) => Effect.Effect<A, E>,
) =>
  Effect.runPromise(
    Effect.flatMap(makeClient, body).pipe(
      Effect.provide(
        Layer.mergeAll(
          Layer.mergeAll(ThreadsLive, MessagesLive).pipe(
            Layer.provideMerge(AuthorizationAllow),
            Layer.provide(
              Layer.mergeAll(ThreadService.layerMemory, MessageService.layerMemory, runner),
            ),
          ),
          HttpServer.layerServices,
        ),
      ),
      Effect.scoped,
    ),
  );

describe("toSseStream", () => {
  it("passes events through and ends cleanly after the runner's error event", async () => {
    const events = await Effect.runPromise(
      Stream.runCollect(
        toSseStream(
          Stream.make(start(threadId("t-1")), errorEvent).pipe(
            Stream.concat(Stream.fail(modelError)),
          ),
        ),
      ),
    );
    expect(events.map((event) => event.type)).toEqual(["message_start", "error"]);
  });

  it("turns a ThreadNotFound raised mid-stream into a terminal error event", async () => {
    const events = await Effect.runPromise(
      Stream.runCollect(
        toSseStream(Stream.fail(new ThreadNotFound({ id: threadId("t-missing") }))),
      ),
    );
    expect(events).toEqual([errorEvent]);
  });
});

describe("POST /api/threads/:id/messages", () => {
  it("streams the runner's events in order with the thread and text it was given", async () => {
    const calls: Array<{ readonly threadId: ThreadId; readonly text: string }> = [];
    const events = await run(
      fakeRunner((input) => Stream.make(start(input.threadId), delta), calls),
      (client) =>
        Effect.gen(function* () {
          const main = yield* client.threads.main();
          const stream = yield* client.messages.send({
            params: { id: main.id },
            payload: { text: "hello" },
          });
          const collected = yield* Stream.runCollect(stream);
          expect(calls).toEqual([{ threadId: main.id, text: "hello" }]);
          return collected;
        }),
    );
    expect(events.map((event) => event.type)).toEqual(["message_start", "text_delta"]);
  });

  it("ends the SSE stream cleanly when the runner emits error and then fails", async () => {
    const events = await run(
      fakeRunner(
        (input) =>
          Stream.make(start(input.threadId), errorEvent).pipe(
            Stream.concat(Stream.fail(modelError)),
          ),
        [],
      ),
      (client) =>
        Effect.gen(function* () {
          const main = yield* client.threads.main();
          const stream = yield* client.messages.send({
            params: { id: main.id },
            payload: { text: "hello" },
          });
          return yield* Stream.runCollect(stream);
        }),
    );
    expect(events.map((event) => event.type)).toEqual(["message_start", "error"]);
    expect(events[1]).toEqual(errorEvent);
  });

  it("answers ThreadNotFound (404) for an unknown thread before running the agent", async () => {
    const calls: Array<{ readonly threadId: ThreadId; readonly text: string }> = [];
    const missing = threadId("019a0000-0000-7000-8000-000000000009");
    const error = await run(
      fakeRunner(() => Stream.empty, calls),
      (client) =>
        Effect.flip(client.messages.send({ params: { id: missing }, payload: { text: "hello" } })),
    );
    expect(error._tag).toBe("ThreadNotFound");
    if (error._tag === "ThreadNotFound") {
