import {
  type Actor,
  Task,
  type TaskCreate,
  type TaskId,
  type TaskListFilter,
  TaskNotFound,
  TaskService,
  type TaskUpdate,
} from "@bloom/domain";
import { DateTime, Effect, Layer, Schema } from "effect";
import { SqlClient } from "effect/sql";
import { makeEventRepo } from "../repos/events.ts";
