import Foundation

// Short names for the generated wire types (`Components.Schemas.*`, from
// packages/api/openapi.json). The app talks in these; nothing here is
// hand-written on top of the wire shapes except small conveniences.
public typealias BloomTask = Components.Schemas.Task
public typealias BloomTaskStatus = Components.Schemas.TaskStatus
public typealias BloomTaskCreate = Components.Schemas.TaskCreate
public typealias BloomThread = Components.Schemas.Thread
public typealias BloomMessage = Components.Schemas.Message
public typealias BloomMessageRole = Components.Schemas.MessageRole
public typealias BloomMessagePart = Components.Schemas.MessagePart
public typealias BloomUiComponent = Components.Schemas.UiComponent
public typealias BloomUser = Components.Schemas.AuthUser
public typealias ChatStreamEvent = Components.Schemas.ChatStreamEvent

/// Timestamps travel as ISO-8601 strings with milliseconds (`DateTime.formatIso`).
public enum BloomDate {
    private static let withFraction = Date.ISO8601FormatStyle(includingFractionalSeconds: true)
    private static let withoutFraction = Date.ISO8601FormatStyle()

    /// Parses a server timestamp; `nil` when the string is not ISO-8601.
    public static func parse(_ string: String) -> Date? {
        (try? withFraction.parse(string)) ?? (try? withoutFraction.parse(string))
    }

    /// Formats a date the way the server writes them.
    public static func format(_ date: Date) -> String {
        withFraction.format(date)
    }
}

extension BloomTaskStatus {
    /// Statuses the task list shows (the web's `OPEN`): not done, not dropped.
    public static let open: [BloomTaskStatus] = [.inbox, .next, .scheduled, .waiting]

    public var isOpen: Bool { Self.open.contains(self) }

    /// The web's label for each status.
    public var label: String {
        switch self {
        case .inbox: "Inbox"
        case .next: "Next"
        case .scheduled: "Scheduled"
        case .waiting: "Waiting"
        case .done: "Done"
        case .dropped: "Dropped"
        }
    }
}

extension BloomTask {
    public var dueDate: Date? { due.flatMap(BloomDate.parse) }
    public var scheduledDate: Date? { scheduledFor.flatMap(BloomDate.parse) }
    public var createdDate: Date? { BloomDate.parse(createdAt) }
}

extension BloomMessage {
    public var createdDate: Date? { BloomDate.parse(createdAt) }

    /// Text of all `text` parts joined with newlines (the domain's `messageText`).
    public var text: String {
        parts.compactMap { part in
            if case let .text(text) = part { text.text } else { nil }
        }
        .joined(separator: "\n")
    }
}

extension ChatStreamEvent {
    /// `message_end` and `error` end a run; nothing follows them (ADR 0013).
    public var isTerminal: Bool {
        switch self {
        case .messageEnd, .error: true
        default: false
        }
    }
}

import Foundation
import OpenAPIRuntime

/// Everything a call to the Bloom API can fail with, in terms the app acts on.
public enum BloomAPIError: Error, Equatable, Sendable {
    /// No valid session (401). The app signs out and shows sign-in.
    case unauthorized
    /// The thing asked for does not exist (404).
    case notFound
    /// The server rejected the request as malformed (400).
    case badRequest
    /// Any other status the contract does not describe.
    case unexpectedStatus(Int)
    /// The server could not be reached, or the connection dropped or timed out.
    case unreachable
    /// The response did not match the contract.
    case invalidResponse

    /// Calm, user-facing text. Never includes server detail.
    public var message: String {
        switch self {
        case .unauthorized: "Please sign in again."
        case .notFound: "That isn't there anymore."
        case .badRequest, .unexpectedStatus, .invalidResponse:
            "That didn't go through. Give it a moment and try again."
        case .unreachable: "Bloom can't reach the server right now."
        }
    }

    /// Maps any error thrown by the generated client or the transport.
    public static func from(_ error: any Error) -> BloomAPIError {
        if let error = error as? BloomAPIError { return error }
        if let error = error as? ClientError { return from(error.underlyingError) }
        if error is URLError { return .unreachable }
        if error is DecodingError { return .invalidResponse }
        if error is CancellationError { return .unreachable }
        return .invalidResponse
    }
}

import Foundation
import HTTPTypes
import OpenAPIRuntime

/// Where the API client gets the session token from (the Keychain in the app).
public protocol TokenProvider: Sendable {
    func currentToken() async -> String?
}

/// A fixed token (tests, previews).
public struct StaticTokenProvider: TokenProvider {
    let token: String?
    public init(_ token: String?) { self.token = token }
    public func currentToken() async -> String? { token }
}

/// Sends `Authorization: Bearer <token>` on every request when a token exists
/// (ADR 0018). The server's Better Auth `bearer` plugin turns it back into a
/// session; the web keeps using its cookie.
struct BearerTokenMiddleware: ClientMiddleware {
    let tokens: any TokenProvider

    func intercept(
        _ request: HTTPRequest,
        body: HTTPBody?,
        baseURL: URL,
        operationID: String,
        next: @Sendable (HTTPRequest, HTTPBody?, URL) async throws -> (HTTPResponse, HTTPBody?)
    ) async throws -> (HTTPResponse, HTTPBody?) {
        var request = request
        if let token = await tokens.currentToken() {
            request.headerFields[.authorization] = "Bearer \(token)"
        }
        return try await next(request, body, baseURL)
    }
}

import Foundation
import OpenAPIRuntime

/// Decodes the body of `POST /api/threads/{id}/messages` (Server-Sent Events)
/// into `ChatStreamEvent`s.
///
/// The request itself goes through the generated client; this only turns the
/// `text/event-stream` bytes into the generated `ChatStreamEvent` enum. SSE
/// framing is parsed by OpenAPIRuntime. The server writes one `data:` line of
/// JSON per event (fixtures in packages/api/test/fixtures/chat-stream).
///
/// Contract (ADR 0013): `message_start`, then tool and UI events, then
/// `text_delta`s, then `message_end`; or `error`, which is terminal and
/// carries text that is safe to show. The sequence finishes after the first
/// terminal event without waiting for the connection to close.
public enum ChatStream {
    /// Effect's reserved event name for a stream that failed on the server
    /// (`HttpApiBuilder`). Bloom's handler never fails its stream, so this
    /// only appears on a server defect.
    public static let failureEventName = "effect/http-api/stream/failure"

    /// Event types this client understands. Anything else is skipped, so a
    /// newer server can add events without breaking older apps.
    public static let knownTypes: Set<String> = [
        "message_start", "text_delta", "tool_call", "tool_result",
        "ui_component", "tasks_changed", "message_end", "error",
    ]

    public enum Failure: Error, Equatable, Sendable {
        /// The server reported a failure through the reserved failure event.
        case serverFailure
        /// The connection ended before `message_end` or `error`.
        case endedEarly
    }

    private struct TypeProbe: Decodable {
        let type: String
    }

    /// Events from raw SSE bytes. Throws `DecodingError` for a known event
    /// whose JSON does not match the contract.
    public static func events<Bytes>(
        from bytes: Bytes
    ) -> AsyncThrowingStream<ChatStreamEvent, any Error>
    where Bytes: AsyncSequence & Sendable, Bytes.Element == ArraySlice<UInt8> {
        AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    let decoder = JSONDecoder()
                    for try await sse in bytes.asDecodedServerSentEvents() {
                        if sse.event == failureEventName { throw Failure.serverFailure }
                        guard let data = sse.data?.data(using: .utf8), !data.isEmpty else { continue }
                        let probe = try decoder.decode(TypeProbe.self, from: data)
                        guard knownTypes.contains(probe.type) else { continue }
                        let event = try decoder.decode(ChatStreamEvent.self, from: data)
                        continuation.yield(event)
                        if event.isTerminal {
                            continuation.finish()
                            return
                        }
                    }
                    throw Failure.endedEarly
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}

import Foundation
import OpenAPIRuntime
import OpenAPIURLSession

/// The Bloom API for the app: thin async wrappers over the generated client
/// (`Client`, from packages/api/openapi.json) that return wire models and
/// throw `BloomAPIError`. No request or response shape is written by hand.
///
/// Two generated clients share one configuration: plain calls use a session
/// with a 20 s idle timeout (the web's `REQUEST_TIMEOUT`); the chat stream uses
/// one that tolerates two minutes of silence while the model thinks (the
/// web's `STREAM_IDLE_TIMEOUT`; the server fails a stream silent for 60 s).
public struct BloomAPI: Sendable {
    public let serverURL: URL
    let client: Client
    let streamingClient: Client

    public static let requestTimeout: TimeInterval = 20
    public static let streamIdleTimeout: TimeInterval = 120

    /// - Parameters:
    ///   - serverURL: Origin of the Bloom server, e.g. `http://localhost:3000`.
    ///     Paths in the contract already start with `/api`.
    ///   - tokens: Source of the bearer token for every request.
    ///   - transport: Override for tests; defaults to URLSession.
    public init(serverURL: URL, tokens: any TokenProvider, transport: (any ClientTransport)? = nil) {
        self.serverURL = serverURL
        let middlewares: [any ClientMiddleware] = [BearerTokenMiddleware(tokens: tokens)]
        client = Client(
            serverURL: serverURL,
            transport: transport ?? Self.urlSessionTransport(idleTimeout: Self.requestTimeout, resourceTimeout: 60),
            middlewares: middlewares
        )
        streamingClient = Client(
            serverURL: serverURL,
            transport: transport
                ?? Self.urlSessionTransport(idleTimeout: Self.streamIdleTimeout, resourceTimeout: 15 * 60),
            middlewares: middlewares
        )
    }

    static func urlSessionTransport(idleTimeout: TimeInterval, resourceTimeout: TimeInterval) -> URLSessionTransport {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.timeoutIntervalForRequest = idleTimeout
        configuration.timeoutIntervalForResource = resourceTimeout
        configuration.waitsForConnectivity = false
        configuration.httpCookieStorage = nil
        configuration.httpShouldSetCookies = false
        return URLSessionTransport(configuration: .init(session: URLSession(configuration: configuration)))
    }

    /// Runs a generated call and maps transport and decoding failures.
    private func call<T>(_ body: () async throws -> T) async throws(BloomAPIError) -> T {
        do {
            return try await body()
        } catch {
            throw BloomAPIError.from(error)
        }
    }

    // MARK: - Health and identity

    /// `GET /api/health` (no session needed).
    public func health() async throws(BloomAPIError) -> Components.Schemas.HealthStatus {
        let output = try await call { try await client.health_check() }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    /// `GET /api/me`: who the session belongs to.
    public func me() async throws(BloomAPIError) -> BloomUser {
        let output = try await call { try await client.me_get() }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    // MARK: - Threads and messages

    /// `GET /api/threads/main`: the single ongoing conversation.
    public func mainThread() async throws(BloomAPIError) -> BloomThread {
        let output = try await call { try await client.threads_main() }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    /// `GET /api/threads/{id}/messages`: history, oldest first.
    public func messages(threadId: String, limit: Int? = nil) async throws(BloomAPIError) -> [BloomMessage] {
        let output = try await call {
            try await client.threads_messages(path: .init(id: threadId), query: .init(limit: limit))
        }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case .notFound: throw .notFound
        case .badRequest: throw .badRequest
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    /// `POST /api/threads/{id}/messages`: sends the user's turn and streams
    /// the reply. Throws before streaming for HTTP errors (404, 401); the
    /// returned sequence throws for stream-level failures (see `ChatStream`).
    public func send(
        threadId: String,
        text: String
    ) async throws(BloomAPIError) -> AsyncThrowingStream<ChatStreamEvent, any Error> {
        let output = try await call {
            try await streamingClient.messages_send(path: .init(id: threadId), body: .json(.init(text: text)))
        }
        switch output {
        case let .ok(ok):
            let body = try await call { try ok.body.textEventStream }
            return ChatStream.events(from: body)
        case .unauthorized: throw .unauthorized
        case .notFound: throw .notFound
        case .badRequest: throw .badRequest
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    // MARK: - Tasks

    /// `GET /api/tasks`, optionally filtered by status; creation order.
    public func tasks(status: [BloomTaskStatus]? = nil) async throws(BloomAPIError) -> [BloomTask] {
        let output = try await call { try await client.tasks_list(query: .init(status: status)) }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case .badRequest: throw .badRequest
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    /// `POST /api/tasks`.
    public func createTask(_ input: BloomTaskCreate) async throws(BloomAPIError) -> BloomTask {
        let output = try await call { try await client.tasks_create(body: .json(input)) }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case .badRequest: throw .badRequest
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }

    /// `POST /api/tasks/{id}/complete`.
    public func completeTask(id: String) async throws(BloomAPIError) -> BloomTask {
        let output = try await call { try await client.tasks_complete(path: .init(id: id)) }
        switch output {
        case let .ok(ok): return try await call { try ok.body.json }
        case .unauthorized: throw .unauthorized
        case .notFound: throw .notFound
        case let .undocumented(status, _): throw .unexpectedStatus(status)
        }
    }
}

import Foundation

private final class BundleToken {}

/// Test fixtures copied into the test bundle (see project.yml).
enum Fixtures {
    static let bundle = Bundle(for: BundleToken.self)

    /// Bytes of `packages/api/test/fixtures/chat-stream/<name>.sse`.
    static func chatStream(_ name: String) throws -> Data {
        let directory = try #require(bundle.url(forResource: "chat-stream", withExtension: nil))
        return try Data(contentsOf: directory.appending(path: "\(name).sse"))
    }

    /// `data` delivered in chunks of `size` bytes, as a network would.
    static func chunks(_ data: Data, size: Int) -> AsyncStream<ArraySlice<UInt8>> {
        let bytes = [UInt8](data)
        return AsyncStream { continuation in
            var offset = 0
            while offset < bytes.count {
                let end = min(offset + size, bytes.count)
                continuation.yield(bytes[offset..<end])
                offset = end
            }
            continuation.finish()
        }
    }

    static func chunks(_ text: String, size: Int = 1 << 20) -> AsyncStream<ArraySlice<UInt8>> {
        chunks(Data(text.utf8), size: size)
    }
}

import BloomKit
import Foundation
import Testing

/// Decoding the chat SSE stream (ADR 0013) from recorded server output.
@Suite("Chat stream decoding")
struct ChatStreamTests {
    private func collect(
        _ bytes: AsyncStream<ArraySlice<UInt8>>
    ) async throws -> [ChatStreamEvent] {
        var events: [ChatStreamEvent] = []
        for try await event in ChatStream.events(from: bytes) {
            events.append(event)
        }
        return events
    }

    private func kinds(_ events: [ChatStreamEvent]) -> [String] {
        events.map { event in
            switch event {
            case .messageStart: "message_start"
            case .textDelta: "text_delta"
            case .toolCall: "tool_call"
            case .toolResult: "tool_result"
            case .uiComponent: "ui_component"
            case .tasksChanged: "tasks_changed"
            case .messageEnd: "message_end"
            case .error: "error"
            }
        }
    }

    @Test("a plain reply: start, deltas, end with the persisted message")
    func plainReply() async throws {
        let events = try await collect(Fixtures.chunks(Fixtures.chatStream("plain-reply"), size: 1 << 16))
        #expect(kinds(events) == ["message_start", "text_delta", "text_delta", "message_end"])
        guard case let .messageEnd(end) = events.last else {
            Issue.record("expected message_end last")
            return
        }
        #expect(end.message.role == .assistant)
        #expect(end.message.text == "Morning. Nothing urgent today.")
        #expect(end.message.createdDate == BloomDate.parse("2026-10-05T07:30:00.000Z"))
    }

    @Test("a tool round: tool parts and tasks_changed come before the text")
    func toolRound() async throws {
        let events = try await collect(Fixtures.chunks(Fixtures.chatStream("tool-round"), size: 1 << 16))
        #expect(kinds(events) == [
            "message_start", "tool_call", "tool_result", "tasks_changed",
            "text_delta", "text_delta", "message_end",
        ])
        guard case let .toolCall(call) = events[1], case let .toolResult(result) = events[2] else {
            Issue.record("expected tool_call then tool_result")
            return
        }
        #expect(call.name == "create_task")
        #expect(call.toolCallId == result.toolCallId)
        #expect(result.ok)
        guard case let .messageEnd(end) = events.last else {
            Issue.record("expected message_end last")
            return
        }
        let cards = end.message.parts.compactMap { part -> Components.Schemas.TaskCard? in
            if case let .uiComponent(ui) = part, case let .taskCard(card) = ui.component { card } else { nil }
        }
        #expect(cards.map(\.title) == ["Water the ferns"])
        #expect(end.message.text == "Added “Water the ferns”.")
    }

    @Test("error is terminal and carries calm text; the stream finishes cleanly")
    func modelError() async throws {
        let events = try await collect(Fixtures.chunks(Fixtures.chatStream("model-error"), size: 1 << 16))
        #expect(kinds(events) == ["message_start", "text_delta", "error"])
        guard case let .error(error) = events.last else {
            Issue.record("expected error last")
            return
        }
        #expect(error.message.hasPrefix("I couldn't reach my thinking"))
    }

    @Test("events survive any chunking of the bytes", arguments: [1, 2, 7, 64, 300])
    func chunking(size: Int) async throws {
        let data = try Fixtures.chatStream("tool-round")
        let whole = try await collect(Fixtures.chunks(data, size: 1 << 20))
        let chunked = try await collect(Fixtures.chunks(data, size: size))
        #expect(chunked == whole)
        #expect(chunked.count == 7)
    }

    @Test("CRLF line endings are accepted")
    func crlf() async throws {
        let text = try #require(String(data: Fixtures.chatStream("plain-reply"), encoding: .utf8))
        let events = try await collect(Fixtures.chunks(text.replacingOccurrences(of: "\n", with: "\r\n")))
        #expect(kinds(events) == ["message_start", "text_delta", "text_delta", "message_end"])
    }

    @Test("the server's reserved failure event fails the sequence")
    func serverFailure() async throws {
        let text = """
            data: {"type":"message_start","messageId":"m","threadId":"t"}

            event: effect/http-api/stream/failure
            data: [{"_tag":"Die","defect":"boom"}]


            """
        await #expect(throws: ChatStream.Failure.serverFailure) {
            _ = try await collect(Fixtures.chunks(text))
        }
    }

    @Test("unknown event types are skipped, so a newer server does not break the app")
    func unknownEventsSkipped() async throws {
        let text = """
            data: {"type":"message_start","messageId":"m","threadId":"t"}

            data: {"type":"reasoning_delta","messageId":"m","delta":"hmm"}

            data: {"type":"error","message":"Not now."}


            """
        let events = try await collect(Fixtures.chunks(text))
        #expect(kinds(events) == ["message_start", "error"])
    }

    @Test("a stream that ends without message_end or error is a failure")
    func endedEarly() async throws {
        let text = """
            data: {"type":"message_start","messageId":"m","threadId":"t"}

            data: {"type":"text_delta","messageId":"m","delta":"Hel"}


            """
        await #expect(throws: ChatStream.Failure.endedEarly) {
            _ = try await collect(Fixtures.chunks(text))
        }
    }

    @Test("a known event that breaks the contract is a decoding error")
    func malformedKnownEvent() async throws {
        let text = """
            data: {"type":"text_delta","messageId":"m"}


            """
        await #expect(throws: DecodingError.self) {
            _ = try await collect(Fixtures.chunks(text))
        }
    }

    @Test("nothing after a terminal event is read")
    func stopsAtTerminal() async throws {
        let text = """
            data: {"type":"error","message":"Not now."}

            data: this is not json


            """
        let events = try await collect(Fixtures.chunks(text))
        #expect(kinds(events) == ["error"])
    }
}

import Foundation
import HTTPTypes
import OpenAPIRuntime
import Synchronization

/// A `ClientTransport` that answers from a closure and records every request.
final class FakeTransport: ClientTransport, Sendable {
    struct Recorded: Sendable {
        let request: HTTPRequest
        let body: String?
        let operationID: String
    }

    typealias Responder = @Sendable (HTTPRequest) -> (HTTPResponse.Status, String, String)

    private let responder: Responder
    private let log = Mutex<[Recorded]>([])

    /// `respond` returns status, content type and body for each request.
    init(_ respond: @escaping Responder) {
        responder = respond
    }

    var requests: [Recorded] { log.withLock { $0 } }

    func send(
        _ request: HTTPRequest,
        body: HTTPBody?,
        baseURL: URL,
        operationID: String
    ) async throws -> (HTTPResponse, HTTPBody?) {
        let bodyText: String? =
            if let body { try await String(collecting: body, upTo: 1 << 20) } else { nil }
        log.withLock { $0.append(Recorded(request: request, body: bodyText, operationID: operationID)) }
        let (status, contentType, text) = responder(request)
        var response = HTTPResponse(status: status)
        response.headerFields[.contentType] = contentType
        return (response, HTTPBody(text))
    }

    static func json(_ status: HTTPResponse.Status = .ok, _ body: String) -> Responder {
        { _ in (status, "application/json", body) }
    }
}

import BloomKit
import Foundation
import HTTPTypes
import Testing

/// The facade over the generated client, against a fake transport.
@Suite("Bloom API client")
struct BloomAPITests {
    static let server = URL(string: "http://bloom.test")!

    static let taskJSON = """
        {"id":"019a0000-0000-7000-8000-0000000000c3","title":"Water the ferns","notes":null,
         "status":"next","due":"2026-10-06T17:00:00.000Z","scheduledFor":null,"effort":1,
         "energyKind":"physical","area":"Home","source":"agent","parentId":null,"completedAt":null,
         "createdAt":"2026-10-05T07:30:00.000Z","updatedAt":"2026-10-05T07:30:00.000Z"}
        """

    private func api(_ transport: FakeTransport, token: String? = "tok_123") -> BloomAPI {
        BloomAPI(serverURL: Self.server, tokens: StaticTokenProvider(token), transport: transport)
    }

    @Test("sends the bearer token and the status filter as repeated query items")
    func tasksRequest() async throws {
        let transport = FakeTransport(FakeTransport.json("[\(Self.taskJSON)]"))
        let tasks = try await api(transport).tasks(status: [.inbox, .next])

        let request = try #require(transport.requests.first?.request)
        #expect(request.method == .get)
        #expect(request.path == "/api/tasks?status=inbox&status=next")
        #expect(request.headerFields[.authorization] == "Bearer tok_123")

        let task = try #require(tasks.first)
        #expect(task.title == "Water the ferns")
        #expect(task.status == .next)
        #expect(task.effort == 1)
        #expect(task.energyKind == .physical)
        #expect(task.notes == nil)
        #expect(task.dueDate == BloomDate.parse("2026-10-06T17:00:00Z"))
    }

    @Test("without a token no Authorization header is sent")
    func noToken() async throws {
        let transport = FakeTransport(FakeTransport.json(#"{"status":"ok","service":"bloom-server","time":"2026-10-05T07:30:00.000Z"}"#))
        let health = try await api(transport, token: nil).health()
        #expect(health.service == .bloomServer)
        #expect(transport.requests.first?.request.headerFields[.authorization] == nil)
    }

    @Test("401 becomes .unauthorized")
    func unauthorized() async throws {
        let transport = FakeTransport(FakeTransport.json(.unauthorized, #"{"_tag":"Unauthorized","message":"Please sign in."}"#))
        await #expect(throws: BloomAPIError.unauthorized) {
            _ = try await api(transport).mainThread()
        }
    }

    @Test("404 on complete becomes .notFound; undocumented 400 becomes .badRequest")
    func statuses() async throws {
        let notFound = FakeTransport(FakeTransport.json(.notFound, #"{"_tag":"TaskNotFound","id":"x"}"#))
        await #expect(throws: BloomAPIError.notFound) {
            _ = try await api(notFound).completeTask(id: "x")
        }
        let bad = FakeTransport { _ in (.badRequest, "application/json", "") }
        await #expect(throws: BloomAPIError.badRequest) {
            _ = try await api(bad).createTask(.init(title: "x"))
        }
    }

