import { ThreadService } from "@bloom/domain";
import { BunRuntime } from "@effect/platform-bun";
import { Config, Effect } from "effect";
import { SqlClient } from "effect/sql";
import { DbLive } from "../src/index.ts";

const seed = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;
  // Better Auth looks users up by lowercased email (findUserByEmail), so the
  // seeded row must match that form or the magic-link flow never finds it.
  const email = (yield* Config.NonEmptyString("BLOOM_OWNER_EMAIL")).toLowerCase();
  const name = yield* Config.NonEmptyString("BLOOM_OWNER_NAME");

  // Better Auth owns the "user" table and its camelCase identifiers; raw text
  // in the template is not run through the snake_case transform.
  const existing = yield* sql<{ id: string }>`SELECT "id" FROM "user" WHERE "email" = ${email}`;
  if (existing.length === 0) {
    const now = new Date();
    yield* sql`INSERT INTO "user" ("id", "name", "email", "emailVerified", "createdAt", "updatedAt")
               VALUES (${crypto.randomUUID()}, ${name}, ${email}, true, ${now}, ${now})`;
    yield* Effect.log("seed: created owner user");
  } else {
    yield* Effect.log("seed: owner user already present");
  }

  const threads = yield* ThreadService;
  const main = yield* threads.ensureMain;
  yield* Effect.log(`seed: main thread ${main.id} (created ${main.createdAt.toString()})`);
});

BunRuntime.runMain(seed.pipe(Effect.provide(DbLive)));
import { PgClient } from "@effect/sql-pg";
import { Config, type Layer, type Redacted, String } from "effect";
import type { SqlClient, SqlError } from "effect/sql";

/**
 * Columns are snake_case in SQL and camelCase in TypeScript: the client
 * rewrites identifiers on the way in and result keys on the way out.
 * `transformJson: false` keeps jsonb payloads (message parts, event payloads)
 * byte-for-byte intact; only top-level column names are transformed.
 */
const transforms = {
  transformQueryNames: String.camelToSnake,
  transformResultNames: String.snakeToCamel,
  transformJson: false,
  applicationName: "bloom",
} as const;

/** Postgres client configured from `DATABASE_URL`. Provides `PgClient` and `SqlClient`. */
export const PgLive = PgClient.layerConfig({
  url: Config.Redacted("DATABASE_URL"),
  transformQueryNames: Config.succeed(transforms.transformQueryNames),
  transformResultNames: Config.succeed(transforms.transformResultNames),
  transformJson: Config.succeed(transforms.transformJson),
  applicationName: Config.succeed(transforms.applicationName),
});

/** Postgres client for an explicit connection URL (tests, one-off scripts). */
export const makePgLayer = (
  url: Redacted.Redacted,
): Layer.Layer<PgClient.PgClient | SqlClient.SqlClient, SqlError.SqlError> =>
  PgClient.layer({ url, ...transforms });

