import Foundation
import Security

/// One generic-password Keychain entry holding a UTF-8 string.
///
/// Items are `AfterFirstUnlockThisDeviceOnly`: readable by extensions and
/// background work once the phone has been unlocked after boot, never synced
/// to iCloud or restored to another device.
public struct KeychainItem: Sendable {
    public struct Failure: Error, Equatable, Sendable {
        public let status: OSStatus
    }

    public let service: String
    public let account: String
    /// Shared access group for the app and its extensions; `nil` uses the app's default.
    public let accessGroup: String?

    public init(service: String, account: String, accessGroup: String? = nil) {
        self.service = service
        self.account = account
        self.accessGroup = accessGroup
    }

    private var query: [String: Any] {
        var query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
        if let accessGroup { query[kSecAttrAccessGroup as String] = accessGroup }
        return query
    }

    /// The stored string, or `nil` when absent (or unreadable).
    public func read() -> String? {
        var query = query
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne
        var result: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &result) == errSecSuccess,
              let data = result as? Data
        else { return nil }
        return String(data: data, encoding: .utf8)
    }

    /// Stores `value`, replacing any previous one.
    public func write(_ value: String) throws(Failure) {
        let data = Data(value.utf8)
        let update: [String: Any] = [
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
        ]
        var status = SecItemUpdate(query as CFDictionary, update as CFDictionary)
        if status == errSecItemNotFound {
            var insert = query
            insert.merge(update) { _, new in new }
            status = SecItemAdd(insert as CFDictionary, nil)
        }
        guard status == errSecSuccess else { throw Failure(status: status) }
    }

    /// Removes the entry; succeeds when it was already absent.
    public func delete() throws(Failure) {
        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else { throw Failure(status: status) }
    }
}

import Foundation

/// A one-time sign-in link from `bun run auth:link` (ADR 0018), in either form:
///
/// - the magic link itself, pasted:
///   `http://localhost:5173/api/auth/magic-link/verify?token=…&callbackURL=…`
/// - the app's deep link from `bun run auth:link --ios`:
///   `bloom://sign-in?link=<the magic link, percent-encoded>`
///
/// The link's origin is the server the app will talk to.
public struct SignInLink: Equatable, Sendable {
    public static let verifyPath = "/api/auth/magic-link/verify"

    /// The magic link to open (always http or https).
    public let verifyURL: URL

    /// Origin of the server, e.g. `http://localhost:3000`.
    public var server: URL {
        var components = URLComponents()
        components.scheme = verifyURL.scheme
        components.host = verifyURL.host()
        components.port = verifyURL.port
        // A scheme and a host always make a valid URL; fall back to the link itself.
        return components.url ?? verifyURL
    }

    /// Parses pasted text or an opened URL; `nil` when it is not a sign-in link.
    public init?(_ text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let url = URL(string: trimmed) else { return nil }
        self.init(url: url)
    }

    public init?(url: URL) {
        if url.scheme == "bloom" {
            guard url.host() == "sign-in",
                  let inner = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                      .queryItems?.first(where: { $0.name == "link" })?.value,
                  let innerURL = URL(string: inner)
            else { return nil }
            self.init(verify: innerURL)
        } else {
            self.init(verify: url)
        }
    }

    private init?(verify url: URL) {
        guard let scheme = url.scheme, scheme == "http" || scheme == "https",
              url.host() != nil,
              url.path() == Self.verifyPath,
              let token = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                  .queryItems?.first(where: { $0.name == "token" })?.value,
              !token.isEmpty
        else { return nil }
        verifyURL = url
    }

    /// The same link against another origin (the user overrode the server).
    public func with(server: URL) -> SignInLink? {
        guard var components = URLComponents(url: verifyURL, resolvingAgainstBaseURL: false) else { return nil }
        components.scheme = server.scheme
        components.host = server.host()
        components.port = server.port
        guard let url = components.url else { return nil }
        return SignInLink(verify: url)
    }
}

import Foundation

/// The signed-in session: which server, the bearer token, and who it belongs to.
///
/// The token lives in the Keychain; the server origin and the cached user
/// (shown while offline) live in `UserDefaults`. Both can be pointed at an
/// app group so extensions share the session.
public struct SessionStore: TokenProvider, @unchecked Sendable {
    // `UserDefaults` is documented as thread-safe; it is not annotated Sendable.
    let keychain: KeychainItem
    let defaults: UserDefaults

    static let serverKey = "bloom.session.server"
    static let userKey = "bloom.session.user"

    public init(keychain: KeychainItem, defaults: UserDefaults) {
        self.keychain = keychain
        self.defaults = defaults
    }

    /// The app's own store.
    public static let standard = SessionStore(
        keychain: KeychainItem(service: "dev.bloom.session", account: "bearer"),
        defaults: .standard
    )

    public var serverURL: URL? { defaults.url(forKey: Self.serverKey) }

    public var token: String? { keychain.read() }

    /// The user the session belonged to when last confirmed.
    public var cachedUser: BloomUser? {
        defaults.data(forKey: Self.userKey).flatMap { try? JSONDecoder().decode(BloomUser.self, from: $0) }
    }

    /// Signed in means a server and a token are both present.
    public var isSignedIn: Bool { serverURL != nil && token != nil }

    public func currentToken() async -> String? { keychain.read() }

    public func save(server: URL, token: String, user: BloomUser) throws(KeychainItem.Failure) {
        try keychain.write(token)
        defaults.set(server, forKey: Self.serverKey)
        remember(user)
    }

    public func remember(_ user: BloomUser) {
        if let data = try? JSONEncoder().encode(user) { defaults.set(data, forKey: Self.userKey) }
    }

    /// Forgets the token and the user. The server origin stays as the default for next time.
    public func clear() {
        try? keychain.delete()
        defaults.removeObject(forKey: Self.userKey)
    }
}

import Foundation

/// The two Better Auth calls the app makes. They are hand-written because
/// `/api/auth/*` belongs to Better Auth and is not part of the HttpApi
/// contract (ADR 0007's one exception; ADR 0018).
public enum AuthClient {
    public enum Failure: Error, Equatable, Sendable {
        /// The link was already used or has expired (15 minutes).
        case linkExpiredOrUsed
        /// The server could not be reached.
        case unreachable
        /// Anything else the server answered.
        case unexpected(status: Int)

        public var message: String {
            switch self {
            case .linkExpiredOrUsed:
                "That link has already been used or has expired. Ask for a fresh one with bun run auth:link --ios."
            case .unreachable:
                "Bloom can't reach the server at that address."
            case .unexpected:
                "Signing in didn't work. Give it a moment and try again."
            }
        }
    }

    /// Response header the `bearer` plugin sets when a request creates a session.
    static let tokenHeader = "set-auth-token"

    /// Opens the magic link the way a browser would, minus the redirect, and
    /// returns the session token Better Auth hands back in `set-auth-token`.
    /// The token is never logged.
    public static func exchange(
        _ link: SignInLink,
        session: URLSession = .shared
    ) async throws(Failure) -> String {
        var request = URLRequest(url: link.verifyURL, timeoutInterval: BloomAPI.requestTimeout)
        request.httpShouldHandleCookies = false
        let response: URLResponse
        do {
            (_, response) = try await session.data(for: request, delegate: NoRedirects())
        } catch {
            throw .unreachable
        }
        guard let http = response as? HTTPURLResponse else { throw .unexpected(status: 0) }
        if let token = http.value(forHTTPHeaderField: tokenHeader), !token.isEmpty {
            return token
        }
        // Better Auth redirects a spent or expired link to its error page.
        if (300..<400).contains(http.statusCode) { throw .linkExpiredOrUsed }
        throw .unexpected(status: http.statusCode)
    }

    /// Revokes the session on the server. Best effort: signing out locally
    /// must not depend on the network.
    public static func signOut(server: URL, token: String, session: URLSession = .shared) async {
        var request = URLRequest(
            url: server.appending(path: "api/auth/sign-out"),
            timeoutInterval: BloomAPI.requestTimeout
        )
        request.httpMethod = "POST"
        request.httpShouldHandleCookies = false
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        _ = try? await session.data(for: request)
    }
}

/// Stops URLSession from following the magic link's redirect to the web app.
private final class NoRedirects: NSObject, URLSessionTaskDelegate, Sendable {
    func urlSession(
        _ session: URLSession,
        task: URLSessionTask,
        willPerformHTTPRedirection response: HTTPURLResponse,
        newRequest request: URLRequest
    ) async -> URLRequest? {
        nil
    }
}

import BloomKit
import Foundation
import Observation

/// App-wide state: who is signed in, and the API client for their server.
@Observable
final class AppModel {
    enum Phase: Equatable {
        case signedOut
        case signingIn
        case signedIn(BloomUser)
    }

    private(set) var phase: Phase
    /// Calm text for the last sign-in failure.
    var signInError: String?
    /// The server the sign-in screen suggests (last used, else localhost).
    private(set) var suggestedServer: String

    private(set) var api: BloomAPI?
    let session: SessionStore

    static let defaultServer = "http://localhost:3000"

    init(session: SessionStore = .standard) {
        self.session = session
        if ProcessInfo.processInfo.arguments.contains("-BloomResetSession") {
            session.clear()
        }
        suggestedServer = session.serverURL?.absoluteString ?? Self.defaultServer
        // Optimistic: a stored session is signed in until the server says otherwise,
        // so the app opens instantly and works with cached data while offline.
        if let server = session.serverURL, session.token != nil {
            api = BloomAPI(serverURL: server, tokens: session)
            phase = .signedIn(
                session.cachedUser ?? BloomUser(id: "", email: "", name: "")
            )
        } else {
            phase = .signedOut
        }
    }

    /// Confirms a stored session with `GET /api/me`. Only a 401 signs out;
    /// being offline keeps the session.
    func refreshUser() async {
        guard let api, case .signedIn = phase else { return }
        do {
            let user = try await api.me()
            session.remember(user)
            phase = .signedIn(user)
        } catch .unauthorized {
            signOutLocally()
        } catch {
            // Offline or a server hiccup: keep going with what we have.
        }
    }

    /// Signs in with pasted text or an opened `bloom://` link. `serverOverride`
    /// replaces the link's origin (the phone reaches the server by another name).
    func signIn(with text: String, serverOverride: String? = nil) async {
        signInError = nil
        guard var link = SignInLink(text) else {
            signInError = "That doesn't look like a Bloom sign-in link. Run bun run auth:link --ios on the server and paste what it prints."
            return
        }
        if let serverOverride, !serverOverride.isEmpty {
            guard let server = URL(string: serverOverride), let moved = link.with(server: server) else {
                signInError = "The server address should look like http://localhost:3000."
                return
            }
            link = moved
        }
        phase = .signingIn
        do {
            let token = try await AuthClient.exchange(link)
            let api = BloomAPI(serverURL: link.server, tokens: StaticTokenProvider(token))
            let user = try await api.me()
            try session.save(server: link.server, token: token, user: user)
            self.api = BloomAPI(serverURL: link.server, tokens: session)
            suggestedServer = link.server.absoluteString
            phase = .signedIn(user)
        } catch let failure as AuthClient.Failure {
            fail(failure.message)
        } catch let failure as BloomAPIError {
            fail(failure.message)
        } catch {
            fail("Signing in didn't work. Give it a moment and try again.")
        }
    }

    private func fail(_ message: String) {
        signInError = message
        phase = .signedOut
    }

    /// `bloom://sign-in?link=…` opened from outside the app.
    func handle(url: URL) {
        guard url.scheme == "bloom", url.host() == "sign-in" else { return }
        Task { await signIn(with: url.absoluteString) }
    }

    /// Revokes the session on the server (best effort) and forgets it here.
    func signOut() async {
        if let server = session.serverURL, let token = session.token {
            await AuthClient.signOut(server: server, token: token)
        }
        signOutLocally()
    }

    /// Any feature that gets a 401 calls this.
    func signOutLocally() {
        session.clear()
        api = nil
        phase = .signedOut
    }
}

import BloomKit
import SwiftUI

/// First-run sign-in (ADR 0018). There is no sign-up: the owner asks the
/// server for a one-time link and opens or pastes it here.
struct SignInView: View {
    @Environment(AppModel.self) private var model
    @State private var link = ""
    @State private var server = ""
    @State private var showServer = false
    @FocusState private var linkFocused: Bool

    private var busy: Bool { model.phase == .signingIn }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: BloomSpacing.s5) {
                VStack(alignment: .center, spacing: BloomSpacing.s3) {
                    Flower(state: busy ? .opening : .closed, size: 72, label: busy ? "Bloom is opening" : "Bloom is resting")
                        .accessibilityIdentifier("bloom-flower")
                    Text("Bloom")
                        .font(.largeTitle.weight(.semibold))
                        .foregroundStyle(BloomPalette.ink)
                }
                .frame(maxWidth: .infinity)
                .padding(.top, BloomSpacing.s7)

                VStack(alignment: .leading, spacing: BloomSpacing.s2) {
                    Text("Sign in with a link")
                        .font(.headline)
                        .foregroundStyle(BloomPalette.ink)
                    Text("On the computer running Bloom, run")
                        .foregroundStyle(BloomPalette.inkMuted)
                    Text("bun run auth:link --ios")
                        .font(.callout.monospaced())
                        .foregroundStyle(BloomPalette.ink)
                        .padding(.vertical, BloomSpacing.s1)
                        .padding(.horizontal, BloomSpacing.s2)
                        .background(BloomPalette.surfaceMuted, in: RoundedRectangle(cornerRadius: BloomSpacing.radiusSmall))
                        .textSelection(.enabled)
                    Text("and open the link it prints on this phone, or paste it here. Links work once and expire after 15 minutes.")
                        .foregroundStyle(BloomPalette.inkMuted)
                }
                .font(.callout)

                VStack(alignment: .leading, spacing: BloomSpacing.s3) {
                    TextField("bloom://sign-in?link=…", text: $link, axis: .vertical)
                        .lineLimit(1...4)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                        .keyboardType(.URL)
                        .focused($linkFocused)
                        .accessibilityIdentifier("signin-link")
                        .padding(BloomSpacing.s3)
                        .background(BloomPalette.surface, in: RoundedRectangle(cornerRadius: BloomSpacing.radiusSmall))
                        .overlay(RoundedRectangle(cornerRadius: BloomSpacing.radiusSmall).strokeBorder(BloomPalette.border))

                    DisclosureGroup("Server address", isExpanded: $showServer) {
                        VStack(alignment: .leading, spacing: BloomSpacing.s2) {
                            TextField(model.suggestedServer, text: $server)
                                .textInputAutocapitalization(.never)
                                .autocorrectionDisabled()
                                .keyboardType(.URL)
                                .accessibilityIdentifier("signin-server")
                                .padding(BloomSpacing.s3)
                                .background(BloomPalette.surface, in: RoundedRectangle(cornerRadius: BloomSpacing.radiusSmall))
                                .overlay(RoundedRectangle(cornerRadius: BloomSpacing.radiusSmall).strokeBorder(BloomPalette.border))
                            Text("Leave empty to use the address inside the link.")
                                .font(.footnote)
                                .foregroundStyle(BloomPalette.inkMuted)
                        }
                        .padding(.top, BloomSpacing.s2)
                    }
                    .font(.callout)
                    .tint(BloomPalette.inkMuted)

                    HStack(spacing: BloomSpacing.s3) {
                        Button {
                            linkFocused = false
                            Task { await model.signIn(with: link, serverOverride: server) }
                        } label: {
                            Text(busy ? "Signing in" : "Sign in")
                        }
                        .buttonStyle(.bloomPrimary)
                        .disabled(busy || link.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                        .accessibilityIdentifier("signin-submit")

                        Button("Paste") {
                            if let text = UIPasteboard.general.string { link = text }
                        }
                        .buttonStyle(.bloomQuiet)
                        .disabled(busy)
                    }
                }

                if let error = model.signInError {
                    Text(error)
                        .font(.callout)
                        .foregroundStyle(BloomPalette.danger)
                        .accessibilityIdentifier("signin-error")
                        .transition(.opacity)
                }
            }
            .padding(BloomSpacing.s5)
            .animation(.easeOut(duration: 0.2), value: model.signInError)
        }
        .scrollDismissesKeyboard(.interactively)
        .background(BloomPalette.page.ignoresSafeArea())
    }
}

